$u=user();$uid=preg_replace('/[^A-Za-z0-9_-]/','',$u['localId']);$dataDir=dirname(__DIR__).'/../private_html/teyza-data';$path=$dataDir.'/'.$uid.'.json';$w=is_file($path)?json_decode((string)file_get_contents($path),true):null;if(!is_array($w))out(404,['ok'=>false,'error'=>'Workspace not found']);
$publicDir=dirname(__DIR__).'/uploads/business-logos';if(!is_dir($publicDir)&&!mkdir($publicDir,0755,true)&&!is_dir($publicDir))out(500,['ok'=>false,'error'=>'Logo storage unavailable']);if(!is_writable($publicDir))out(500,['ok'=>false,'error'=>'Business logo folder is not writable by PHP']);
if($_SERVER['REQUEST_METHOD']==='DELETE'){foreach(glob($publicDir.'/'.$uid.'.*')?:[] as $old)@unlink($old);unset($w['business']['logoUrl']);file_put_contents($path,json_encode($w,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),LOCK_EX);out(200,['ok'=>true,'logoUrl'=>null]);}
if($_SERVER['REQUEST_METHOD']!=='POST')out(405,['ok'=>false,'error'=>'Method not allowed']);
