$f=$_FILES['logo'];if((int)$f['size']>5*1024*1024)out(413,['ok'=>false,'error'=>'Image must be 5 MB or smaller']);$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png'][$mime]??null;if(!$ext)out(415,['ok'=>false,'error'=>'Only JPG and PNG images are accepted']);
